`timescale 1ns/1ps
// =====================================================================
// tb_block_rule — exhaustive test of the 2×2 block physics
// =====================================================================
// Reads golden vectors from block_rule_vectors.mem (generated by
// sim/golden/block_rule.py) and verifies each against the RTL.
// Also checks multiset conservation for every case.
// 648 vectors: 4 gravities × 2 rnd × 3^4 material combos.
// =====================================================================
module tb_block_rule;

	localparam int CELL_BITS = 4;
	localparam int NUM_VECTORS = 2048;

	logic [1:0]           grav_dir;
	logic                 rnd;
	logic [CELL_BITS-1:0] c00, c01, c10, c11;
	logic [CELL_BITS-1:0] n00, n01, n10, n11;

	int pass_count = 0, fail_count = 0, printed = 0;
	localparam int MAXP = 20;

	block_rule #(.CELL_BITS(CELL_BITS)) dut (
		.grav_dir(grav_dir),
		.rnd     (rnd),
		.c00     (c00), .c01(c01), .c10(c10), .c11(c11),
		.n00     (n00), .n01(n01), .n10(n10), .n11(n11)
	);

	// Read vectors file
	integer fd, r;
	int vec_grav, vec_rnd, vc00, vc01, vc10, vc11, vn00, vn01, vn10, vn11;

	task automatic check_vec(int line_num);
		logic out_ok;
		logic cons_ok;
		int in_counts [16];
		int out_counts [16];
		int i;

		// Check output matches golden
		out_ok = (n00 == vn00[CELL_BITS-1:0]) &&
		         (n01 == vn01[CELL_BITS-1:0]) &&
		         (n10 == vn10[CELL_BITS-1:0]) &&
		         (n11 == vn11[CELL_BITS-1:0]);

		// Check conservation (multiset in == multiset out)
		for (i = 0; i < 16; i++) begin
			in_counts[i] = 0;
			out_counts[i] = 0;
		end
		in_counts[c00]++;  in_counts[c01]++;  in_counts[c10]++;  in_counts[c11]++;
		out_counts[n00]++; out_counts[n01]++; out_counts[n10]++; out_counts[n11]++;
		cons_ok = 1;
		for (i = 0; i < 16; i++) begin
			if (in_counts[i] != out_counts[i]) cons_ok = 0;
		end

		if (out_ok && cons_ok) begin
			pass_count++;
		end else begin
			fail_count++;
			if (printed < MAXP) begin
				if (!out_ok)
					$display("FAIL vec %0d: grav=%0d rnd=%0d in=(%0h,%0h,%0h,%0h) exp=(%0h,%0h,%0h,%0h) got=(%0h,%0h,%0h,%0h)",
					         line_num, vec_grav, vec_rnd,
					         vc00, vc01, vc10, vc11,
					         vn00, vn01, vn10, vn11,
					         n00, n01, n10, n11);
				if (!cons_ok)
					$display("FAIL vec %0d: CONSERVATION VIOLATED grav=%0d rnd=%0d",
					         line_num, vec_grav, vec_rnd);
				printed++;
			end
		end
	endtask

	initial begin
		fd = $fopen("sim/golden/block_rule_vectors.mem", "r");
		if (fd == 0) begin
			$display("*** FAIL *** cannot open block_rule_vectors.mem");
			$finish;
		end

		for (int i = 0; i < NUM_VECTORS; i++) begin
			r = $fscanf(fd, "%h %h %h %h %h %h %h %h %h %h\n",
			            vec_grav, vec_rnd, vc00, vc01, vc10, vc11,
			            vn00, vn01, vn10, vn11);
			if (r != 10) begin
				$display("*** FAIL *** read error at vector %0d", i);
				fail_count++;
				break;
			end

			// Drive inputs
			grav_dir = vec_grav[1:0];
			rnd      = vec_rnd[0];
			c00      = vc00[CELL_BITS-1:0];
			c01      = vc01[CELL_BITS-1:0];
			c10      = vc10[CELL_BITS-1:0];
			c11      = vc11[CELL_BITS-1:0];

			#10;  // combinational settle time
			check_vec(i);
		end

		$fclose(fd);

		if (fail_count == 0)
			$display("TB tb_block_rule: %0d/%0d PASS", pass_count, pass_count);
		else
			$display("*** FAIL *** tb_block_rule: %0d/%0d failed (%0d total)",
			         fail_count, fail_count, pass_count + fail_count);
		$finish;
	end

endmodule
